import { hexDistance, type AxialCoord, type HexCell } from "./hex.ts";
import { visibleCells } from "./camera.ts";
import { fitCameraToEntities } from "./cameraMath.ts";

export interface WorldEntity extends AxialCoord {
  id: string;
  label: string;
  subtitle?: string;
  type?: "anchor" | "section" | "entity" | "data";
}

export interface WorldRelationship {
  from: string;
  to: string;
  kind?: string;
  active?: boolean;
  muted?: boolean;
}

export interface WorldCameraState {
  center: AxialCoord;
  zoom: number;
  viewportWidth: number;
  viewportHeight: number;
}

export interface WorldModelOptions {
  radius: number;
  cells: HexCell[];
  entities?: WorldEntity[];
  relationships?: WorldRelationship[];
  camera?: Partial<WorldCameraState>;
}

export class WorldModel {
  readonly radius: number;
  readonly cells: HexCell[];
  readonly entities: WorldEntity[];
  readonly relationships: WorldRelationship[];
  readonly camera: WorldCameraState;

  constructor(options: WorldModelOptions) {
    this.radius = options.radius;
    this.cells = [...options.cells];
    this.entities = [...(options.entities ?? [])];
    this.relationships = [...(options.relationships ?? [])];
    this.camera = {
      center: options.camera?.center ?? { q: 0, r: 0 },
      zoom: options.camera?.zoom ?? 1,
      viewportWidth: options.camera?.viewportWidth ?? 0,
      viewportHeight: options.camera?.viewportHeight ?? 0,
    };
  }

  getEntity(id: string) {
    return this.entities.find((entity) => entity.id === id) ?? null;
  }

  getEntitiesAt(coord: AxialCoord) {
    return this.entities.filter((entity) => entity.q === coord.q && entity.r === coord.r);
  }

  getNeighbors(id: string) {
    const entity = this.getEntity(id);
    if (!entity) {
      return [] as WorldEntity[];
    }

    return this.entities.filter((candidate) => {
      if (candidate.id === id) return false;
      return hexDistance(entity, candidate) <= 2;
    });
  }

  getRelationshipsForEntity(id: string) {
    return this.relationships.filter((relationship) => relationship.from === id || relationship.to === id);
  }

  getVisibleCells(camera: WorldCameraState, padding?: number) {
    return visibleCells({
      cells: this.cells,
      camera,
      radius: this.radius,
      padding,
    });
  }

  fitCamera(viewportWidth: number, viewportHeight: number, padding?: number) {
    return fitWorldCameraToEntities({
      entities: this.entities,
      viewportWidth,
      viewportHeight,
      radius: this.radius,
      padding,
    });
  }

  focusEntity(entityId: string, viewportWidth: number, viewportHeight: number, padding?: number) {
    const entity = this.getEntity(entityId);
    if (!entity) {
      return this.fitCamera(viewportWidth, viewportHeight, padding);
    }

    return fitWorldCameraToEntities({
      entities: [entity],
      viewportWidth,
      viewportHeight,
      radius: this.radius,
      padding,
    });
  }

  setCamera(nextCamera: Partial<WorldCameraState>) {
    return new WorldModel({
      radius: this.radius,
      cells: this.cells,
      entities: this.entities,
      relationships: this.relationships,
      camera: {
        ...this.camera,
        ...nextCamera,
      },
    });
  }
}

export function createWorldCameraState(options: Partial<WorldCameraState> = {}): WorldCameraState {
  return {
    center: options.center ?? { q: 0, r: 0 },
    zoom: options.zoom ?? 1,
    viewportWidth: options.viewportWidth ?? 0,
    viewportHeight: options.viewportHeight ?? 0,
  };
}

export function fitWorldCameraToEntities(params: {
  entities: Array<Pick<WorldEntity, "q" | "r">>;
  viewportWidth: number;
  viewportHeight: number;
  radius: number;
  padding?: number;
}) {
  return createWorldCameraState(fitCameraToEntities(params));
}
